async function fetchWithRetry(url, options, attempt = 0) {
  const res = await fetch(url, options);
  if (res.status === 429 && attempt < 5) {
    const retryAfter = res.headers.get('Retry-After');
    const delay = retryAfter ? Number(retryAfter) * 1000 : Math.min(1000 * 2 ** attempt, 30000);
    await new Promise(r => setTimeout(r, delay));
    return fetchWithRetry(url, options, attempt + 1);
  }
  return res;
}

const RETRYABLE_STATUSES = new Set([429, 500, 502, 503, 504]);
async function requestWithRetry(fn, attempt = 0) {
  try { return await fn(); }
  catch (err) {
    const status = err.response?.status;
    const isNetworkError = !err.response;
    if ((isNetworkError || RETRYABLE_STATUSES.has(status)) && attempt < 4) {
      await delay(Math.min(1000 * 2 ** attempt, 15000));
      return requestWithRetry(fn, attempt + 1);
    }
    throw err;
  }
}

function useDebouncedResize(callback, delay = 200) {
  useEffect(() => {
    let timer;
    const handler = () => {
      clearTimeout(timer);
      timer = setTimeout(callback, delay);
    };
    window.addEventListener('resize', handler);
    return () => { window.removeEventListener('resize', handler); clearTimeout(timer); };
  }, [callback, delay]);
}

